      position: absolute; top: 32px; right: 32px;
      background: rgba(217,119,6,0.15); color: var(--copper);
      padding: 8px 16px; border-radius: 20px; font-weight: 700; font-size: 16px;
      border: 1px solid rgba(217,119,6,0.3);
      letter-spacing: 0.05em; text-transform: uppercase;
    }
    .hero-title { font-size: 40px; margin-bottom: 16px; }
    .hero-desc { font-size: 22px; color: var(--text-secondary); line-height: 1.4; }

    /* AI INTEGRATION */
    .ai-section {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 48px;
      display: flex; align-items: center; gap: 40px;
    }
