      width: 120px; height: 120px; border-radius: 50%;
      background: linear-gradient(135deg, rgba(28,100,242,0.2), rgba(63,131,248,0.05));
      display: flex; align-items: center; justify-content: center;
      border: 1px solid rgba(28,100,242,0.3);
      flex-shrink: 0;
    }
    .ai-content { flex: 1; }
    .ai-tags { display: flex; gap: 16px; margin-top: 24px; }
    .ai-tag {
      background: rgba(255,255,255,0.05); border: 1px solid var(--border);
      padding: 10px 20px; border-radius: 30px; font-size: 18px; font-weight: 500;
      color: var(--text);
    }

    /* TABLE SECTION */
    .table-section {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 40px 48px;
      flex: 1;
      display: flex; flex-direction: column;
    }
    .table-header { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 32px; }
    .category-table { width: 100%; border-collapse: collapse; }
    .category-table th { 
      text-align: left; padding: 16px 0; border-bottom: 2px solid var(--border); 
      color: var(--text-secondary); font-size: 18px; text-transform: uppercase; letter-spacing: 0.05em; 
    }
    .category-table td { padding: 20px 0; border-bottom: 1px solid var(--border-light); font-size: 22px; }
    .category-table tr:last-child td { border-bottom: none; }
    .td-category { color: var(--accent-secondary); font-weight: 500; width: 30%; }
    .td-product { font-weight: 600; color: var(--text); width: 50%; }
    .td-status { width: 20%; text-align: right; }
    .status-badge {
      display: inline-block; padding: 6px 16px; border-radius: 20px; font-size: 16px; font-weight: 600;
    }
    .status-new { background: rgba(217,119,6,0.15); color: var(--copper); }
    .status-current { background: rgba(255,255,255,0.05); color: var(--text-secondary); }

    .poster-footer {
      padding: 32px 80px;
      text-align: center; border-top: 1px solid var(--border);
      z-index: 1; position: relative;
    }
    .poster-footer p { font-size: 16px; letter-spacing: 0.1em; text-transform: uppercase; }

    /* MENU */
    .viz-menu { position: fixed; top: 32px; right: 32px; z-index: 9999; }
    .viz-menu-toggle {
      width: 56px; height: 56px; border-radius: 16px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px);
    }
    .viz-menu-dropdown {
      position: absolute; top: 68px; right: 0; min-width: 240px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 16px; padding: 12px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s;
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 14px 20px; border: none; border-radius: 10px;
      background: transparent; color: var(--text); font-size: 16px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 12px;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

  </style>
</head>
<body>
  <div class="bg-glow"></div>
