        </div>
      </div>
      <div class="hero-card">
        <div class="badge-new">NEW LAUNCH</div>
        <div>
          <h2 class="hero-title">Galaxy Buds4 Pro</h2>
          <p class="hero-desc">Next-generation active noise cancellation and high-fidelity audio. Designed to pair seamlessly with every device in the Galaxy ecosystem.</p>
        </div>
        <div style="margin-top: 40px; text-align: right;">
          <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="var(--accent-secondary)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"></path><path d="M13.73 21a2 2 0 0 1-3.46 0"></path></svg>
        </div>
      </div>
    </div>

    <!-- AI INTEGRATION -->
    <div class="ai-section">
      <div class="ai-icon-wrapper">
